async page=>{
 const out='design/prototypes/picsee-browser/qa';
 const results=[],errors=[];page.on('pageerror',e=>errors.push(e.message));
 const check=(condition,label)=>{if(!condition)throw new Error(label);results.push({check:label,passed:true})};
 await page.setViewportSize({width:1019,height:853});await page.goto('http://127.0.0.1:4311/prototypes/picsee-browser/viewer-options.html');
 await page.getByTestId('large-viewer').waitFor();
 check(await page.getByTestId('large-viewer').getAttribute('data-variant')==='immersive','Only C viewer is active');
 check(await page.locator('.review-rail,.variant-selector,.bottom-commandbar').count()===0,'A/B and comparison rail are removed');
 const size=await page.locator('.picture-stage').boundingBox();check(size.height===853,'Viewer uses full viewport height');
 await page.keyboard.press('Escape');await page.locator('.photo-grid').waitFor();
 check(await page.locator('.toolbar,.collection-heading').count()===0,'Both grid banners are removed');
 check(await page.locator('.photo-cell').count()===12,'All thumbnails remain available');
 const first=await page.locator('.photo-cell').first().boundingBox();check(first.y<70,'Grid begins directly below native title strip');
 const toggle=page.getByRole('button',{name:'显示侧栏',exact:true});const toggleBox=await toggle.boundingBox();check(toggleBox.x<20&&toggleBox.y>810,'Sidebar toggle is at window bottom left');
 await toggle.click();check(await page.getByRole('complementary',{name:'文件夹侧栏'}).isVisible(),'Bottom-left toggle opens sidebar');
 await page.getByRole('button',{name:'山间与绿意 4',exact:true}).click();check(await page.locator('.photo-cell').count()===4,'Folder filtering works');
 await page.getByRole('button',{name:'日本 · 山海之间 12',exact:true}).click();
 await page.getByRole('button',{name:'浅色主题',exact:true}).click();
 await page.evaluate(async()=>Promise.all([...document.images].map(i=>i.decode().catch(()=>{}))));
 await page.screenshot({path:out+'/C-grid-light.png'});
 await page.getByRole('button',{name:'搜索图片',exact:true}).click();const search=page.getByRole('searchbox',{name:'搜索当前文件夹'});await search.fill('0343');check(await page.locator('.photo-cell').count()===1,'Bottom search filters images');
 await search.fill('没有匹配');check(await page.getByRole('heading',{name:'没有匹配的图片'}).isVisible(),'Empty search state works');
 await search.fill('');await page.keyboard.press('Escape');check(await page.getByRole('region',{name:'搜索面板'}).count()===0,'Escape closes bottom search panel');
 await page.keyboard.press('Meta+f');check(await search.isVisible(),'Command-F opens relocated search');await page.keyboard.press('Escape');
 await page.getByRole('button',{name:'图片排序',exact:true}).click();await page.getByRole('combobox',{name:'排序方式'}).selectOption('date');check(await page.locator('.photo-name').first().textContent()==='DSC_0351.jpg','Bottom sort changes order');
 await page.getByRole('combobox',{name:'排序方式'}).selectOption('name');await page.getByRole('button',{name:'关闭排序面板',exact:true}).click();
 await page.getByRole('button',{name:'显示图片信息',exact:true}).click();check(await page.getByRole('complementary',{name:'图片信息'}).isVisible(),'Bottom inspector entry works');await page.getByRole('button',{name:'关闭图片信息',exact:true}).click();
 await page.getByRole('button',{name:'深色主题',exact:true}).click();check(await page.locator('html').getAttribute('class')==='theme-dark','Grid dark theme works');await page.screenshot({path:out+'/C-grid-dark.png'});
 await page.locator('[data-photo-id="lakeside"]').click();await page.keyboard.press('Space');await page.getByTestId('large-viewer').waitFor();
 check(await page.locator('.large-image').getAttribute('src')==='assets/lakeside.jpg','Space opens selected image');
 await page.keyboard.press('ArrowRight');check(await page.locator('.large-image').getAttribute('src')==='assets/temple.jpg','Right arrow advances');await page.keyboard.press('ArrowLeft');check(await page.locator('.large-image').getAttribute('src')==='assets/lakeside.jpg','Left arrow returns');
 await page.locator('.picture-stage').click({position:{x:450,y:250}});await page.waitForFunction(()=>document.querySelector('.picture-viewer')?.classList.contains('chrome-asleep'));check(!await page.locator('.zoom-pod').isVisible(),'C controls hide when idle');
 await page.keyboard.press('Tab');await page.waitForFunction(()=>document.activeElement?.getAttribute('aria-label')==='隐藏侧栏');check(await page.locator('.zoom-pod').isVisible(),'Tab restores immersive controls');
 await page.getByRole('button',{name:'隐藏侧栏',exact:true}).click();await page.locator('.picture-stage').click({position:{x:450,y:250}});await page.waitForFunction(()=>document.querySelector('.picture-viewer')?.classList.contains('chrome-asleep'));await page.screenshot({path:out+'/C-viewer-dark.png'});
 await page.keyboard.press('Escape');check(await page.locator('[data-photo-id="lakeside"]').getAttribute('aria-selected')==='true','Esc preserves selected item');
 await page.setViewportSize({width:800,height:680});check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'Narrow grid has no horizontal page overflow');
 await page.setViewportSize({width:1019,height:853});await page.getByRole('button',{name:'浅色主题',exact:true}).click();
 check(errors.length===0,'No browser runtime errors');return {passed:true,checks:results.length,results,errors,timestamp:new Date().toISOString()};
}
